<script setup lang="ts">
import {onMounted,ref,computed} from 'vue'
import {api} from '../api'
const props=defineProps<{modelValue:any}>(),emit=defineEmits(['update:modelValue'])
const tables=ref<any[]>([]),dictionary=ref(props.modelValue.dictionary || '')
const current=computed(()=>tables.value.find(x=>x.value===props.modelValue.table))
onMounted(async()=>{tables.value=(await api('/api/system/system_config/association_tables/')).data})
function table(value:string){const item=tables.value.find(x=>x.value===value);emit('update:modelValue',{table:value,primarykey:item.pk,field:item.pk,searchField:item.fields.map((x:any)=>({field:x.key,title:x.title,search:true,visible:true,width:160}))})}
function update(key:string,value:any){emit('update:modelValue',{...props.modelValue,[key]:value})}
</script>
<template><div class="association-setting"><el-select :model-value="modelValue.table" placeholder="关联数据表" @update:model-value="table"><el-option v-for="item in tables" :key="item.value" :value="item.value" :label="item.label"/></el-select><el-select v-if="current" :model-value="modelValue.field" placeholder="显示字段" @update:model-value="(value:any)=>update('field',value)"><el-option v-for="item in current.fields" :key="item.key" :value="item.key" :label="item.title"/></el-select><el-input v-model="dictionary" placeholder="字典配置键（用于下拉、单选、复选）" @change="update('dictionary',dictionary)"/><template v-if="current"><el-input :model-value="modelValue.primarykey" placeholder="业务主键" @update:model-value="(value:any)=>update('primarykey',value)"/><el-select :model-value="modelValue.treeField" placeholder="树形父字段（留空为普通列表）" clearable @update:model-value="(value:any)=>update('treeField',value)"><el-option v-for="field in current.fields" :key="field.key" :value="field.key" :label="field.title"/></el-select><el-table :data="modelValue.searchField"><el-table-column prop="field" label="字段" min-width="120"/><el-table-column label="显示标题" min-width="150"><template #default="{row}"><el-input v-model="row.title" @change="update('searchField',modelValue.searchField)"/></template></el-table-column><el-table-column label="可见" width="70"><template #default="{row}"><el-checkbox :model-value="row.visible!==false" @update:model-value="row.visible=$event" @change="update('searchField',modelValue.searchField)"/></template></el-table-column><el-table-column label="搜索" width="70"><template #default="{row}"><el-checkbox :model-value="row.search!==false" @update:model-value="row.search=$event" @change="update('searchField',modelValue.searchField)"/></template></el-table-column><el-table-column label="列宽" width="140"><template #default="{row}"><el-input-number v-model="row.width" @change="update('searchField',modelValue.searchField)"/></template></el-table-column></el-table></template></div></template>

<style scoped>.association-setting{display:flex;flex-direction:column;gap:12px;min-width:0}</style>
